<?php $pageTitle='Stock In'; require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/header.php'; $branchId=current_branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){ $pid=(int)$_POST['product_id']; $qty=(int)$_POST['qty']; $pdo->prepare('UPDATE products SET stock_qty=stock_qty+? WHERE id=? AND branch_id=?')->execute([$qty,$pid,$branchId]); $pdo->prepare('INSERT INTO inventory_movements(branch_id,product_id,type,qty,remarks,user_id) VALUES(?, ?, "stock_in", ?, ?, ?)')->execute([$branchId,$pid,$qty,$_POST['remarks'] ?? 'Stock in',$_SESSION['user_id']]); header('Location:index.php'); exit; }
$products=$pdo->prepare('SELECT id,name,barcode FROM products WHERE branch_id=? ORDER BY name'); $products->execute([$branchId]); ?>
<div class="table-card"><h5>Stock In</h5><form method="post"><label>Product</label><select name="product_id" class="form-select mb-2"><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>"><?= htmlspecialchars($p['name']) ?> <?= $p['barcode'] ? '('.htmlspecialchars($p['barcode']).')' : '' ?></option><?php endforeach; ?></select><label>Quantity</label><input class="form-control mb-2" type="number" name="qty" min="1" required><label>Remarks</label><input class="form-control mb-3" name="remarks"><button class="btn btn-primary">Save Stock In</button></form></div>
<?php include __DIR__.'/../includes/footer.php'; ?>
